import numpy as np

def P(x):
    return x**3 + x**2 + x - 10

# Find the positive real root r using numpy's root finding capabilities
# np.roots([1, 1, 1, -10]) returns the roots. We select the real, positive one.
roots = np.roots([1, 1, 1, -10])
r = None
for root in roots:
    if np.isreal(root) and root.real > 0:
        r = root.real
        break

if r is None:
    print("Error: No positive real root found.")
else:
    print(f"r = {r}")
    print("\nCalculating powers of r:")
    # Calculate powers of r up to 18 (based on earlier estimate)
    powers = [r**i for i in range(19)]
    for i, p in enumerate(powers):
        print(f"r^{i}: {p:.4f}")
